CREATE Proc [dbo].[ReportItemStokBySubCate]@Date as datetime,@SubCategoryId as text,@Adj as int = null as Declare @SId as int set @SId = 0;declare @DateTOO as datetime;select @DateTOO = Date from warehouse_store where id =( select min(id) from Warehouse_store where [type] = 'in' and date <= @Date)select @SId = SId from Store where CentarlStore = 1;Declare @ReportName as nvarchar(max);set @ReportName='Item Stock Item Wise';select  CONVERT(VARCHAR(11),@Date,106) as DateFrom,U.Unit,@ReportName as ReportName,iu.PurFactor as UnitQty,c.Category,sc.Subcategory,i.Item,isnull((Select isnull(sum(Qty),0) from WareHouse_Store wh where [Type]='In'and wh.ItemId=i.ItemId and SId = @SId and Date <= @Date and (wh.InvAdjId = @Adj or @Adj is null))- (Select isnull(sum(Qty),0) from WareHouse_Store wh where [Type]='Out'and wh.ItemId=i.ItemId and SId = @SId and Date <= @Date and (wh.InvAdjId = @Adj or @Adj is null)),0)as Balance,Cast(isnull([dbo].uspGetItemAvgRateFuncStock(wh.SId,i.ItemId,@DateTOO,@Date,1),0) as DECIMAL (18,2)) as Rate,iu.IssFactor as Parlevel,(select Unit from Unit where UId = iu.IssUnit) as Store from WareHouse_Store wh inner join Store s on wh.SId=s.SId inner join Item i on wh.ItemId=i.ItemId inner join Subcategory sc on i.SBId = sc.SBId inner join Category c on sc.CId=c.CId inner join ItemUnit iu on i.ItemId=iu.ItemId inner join Unit U on iu.PkUnit=U.UId inner join Split(@SubCategoryId,',') sp on sp.items = sc.SBId where wh.Date <= @Date and wh.SId = @SId   and wh.BRId=0 and (wh.InvAdjId = @Adj or @Adj is null)group by U.Unit,I.ItemId,iu.PurFactor,s.store, c.Category,sc.Subcategory,wh.SId,i.Item,iu.IssUnit,iu.IssFactor